(function () {
  "use strict";

  class DataSet {
    constructor(items) {
      this._items = new Map();
      this._listeners = [];
      if (items) this.add(items);
    }

    add(items) {
      const list = Array.isArray(items) ? items : [items];
      for (const item of list) {
        if (item && item.id !== undefined) this._items.set(item.id, Object.assign({}, item));
      }
      this._emit();
    }

    clear() {
      this._items.clear();
      this._emit();
    }

    get() {
      return Array.from(this._items.values()).map((item) => Object.assign({}, item));
    }

    update(items) {
      const list = Array.isArray(items) ? items : [items];
      for (const item of list) {
        if (!item || item.id === undefined) continue;
        const current = this._items.get(item.id) || {};
        this._items.set(item.id, Object.assign({}, current, item));
      }
      this._emit();
    }

    on(_, callback) {
      if (typeof callback === "function") this._listeners.push(callback);
    }

    _emit() {
      for (const callback of this._listeners) callback();
    }
  }

  class Network {
    constructor(container, data) {
      this.container = container;
      this.nodes = data.nodes;
      this.edges = data.edges;
      this.nodes.on("*", () => this._render());
      this.edges.on("*", () => this._render());
      this._render();
    }

    _render() {
      const nodes = this.nodes.get();
      const edges = this.edges.get();
      const width = Math.max(this.container.clientWidth || 640, 320);
      const height = Math.max(this.container.clientHeight || 340, 220);
      const cx = width / 2;
      const cy = height / 2;
      const radius = Math.max(70, Math.min(width, height) * 0.38);
      const positions = new Map();
      const sorted = nodes.slice().sort((a, b) => Number(a.id) - Number(b.id));

      sorted.forEach((node, idx) => {
        const angle = sorted.length <= 1 ? 0 : (Math.PI * 2 * idx) / sorted.length - Math.PI / 2;
        positions.set(node.id, {
          x: cx + radius * Math.cos(angle),
          y: cy + radius * Math.sin(angle),
        });
      });

      const edgeMarkup = edges.map((edge) => {
        const from = positions.get(edge.from);
        const to = positions.get(edge.to);
        if (!from || !to) return "";
        return `<line x1="${from.x.toFixed(1)}" y1="${from.y.toFixed(1)}" x2="${to.x.toFixed(1)}" y2="${to.y.toFixed(1)}" stroke="#4b5563" stroke-width="1.5" />`;
      }).join("");

      const nodeMarkup = sorted.map((node) => {
        const pos = positions.get(node.id);
        const color = node.color || {};
        const background = color.background || "#40916c";
        const border = color.border || "#52b788";
        const label = String(node.label || node.id);
        const title = String(node.title || label)
          .replace(/&/g, "&amp;")
          .replace(/</g, "&lt;")
          .replace(/>/g, "&gt;");
        return `<g><title>${title}</title><circle cx="${pos.x.toFixed(1)}" cy="${pos.y.toFixed(1)}" r="15" fill="${background}" stroke="${border}" stroke-width="2" /><text x="${pos.x.toFixed(1)}" y="${(pos.y + 4).toFixed(1)}" text-anchor="middle" fill="#eee" font-family="monospace" font-size="12">${label}</text></g>`;
      }).join("");

      this.container.innerHTML = `<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="network topology">${edgeMarkup}${nodeMarkup}</svg>`;
    }
  }

  window.vis = { DataSet, Network };
})();

